export default "using System.Collections;\r\nusing System.Collections.Generic;\r\nusing UnityEngine;\r\nusing System.Linq;\r\nusing UnityEngine.SceneManagement;\r\n\r\nusing v2 = UnityEngine.Vector2;\r\nusing v3 = UnityEngine.Vector3;\r\nusing Gob = UnityEngine.GameObject;\r\n\r\npublic class Tangram : MonoPlus {\r\n    /////////////\r\n    // COMPONENTS\r\n    /////////////\r\n    public Camera cam;\r\n    public Gob canvasGob;\r\n    public Gob boardBounds;\r\n    public List<Gob> pieces;\r\n    public Piece boardPiece;\r\n    public List<Color> pieceColors;\r\n    public Material ghostMat;\r\n    public float maxDist;\r\n    public float dropDist;\r\n    \r\n    ////////\r\n    // DEBUG\r\n    ////////\r\n    List<Gob> trash = new();\r\n    void DrawBounds(Bounds b, float dur=0f) {\r\n        v3 min = b.min; min.y = 0f;\r\n        v3 max = b.max; max.y = 0f;\r\n        Debug.DrawLine(min, new v3(min.x, 0f, max.z), Color.green, dur);\r\n        Debug.DrawLine(new v3(min.x, 0f, max.z), max, Color.green, dur);\r\n        Debug.DrawLine(max, new v3(max.x, 0f, min.z), Color.green, dur);\r\n        Debug.DrawLine(new v3(max.x, 0f, min.z), min, Color.green, dur);\r\n    }\r\n\r\n    ////////\r\n    // STATE\r\n    ////////\r\n    List<List<(int,int)>> allTris;\r\n    List<Piece> placedPieces = new();\r\n    Gob selectedPiece = null;\r\n    Gob selectedPieceGhost = null;\r\n    v3 mouseDownPos = v2.zero;\r\n    float dragDist = 0f;\r\n    v3 selectionOffset = v3.zero;\r\n    bool gameOver = false;\r\n    Bounds boardB;\r\n\r\n    ////////////\r\n    // UTILITIES\r\n    ////////////\r\n    float lerpdt(float lambda, float dt) {\r\n        return 1f - Mathf.Exp(-lambda * dt);\r\n    }\r\n    bool IsPointInPolygon(List<v3> polygon, v3 point) {\r\n        bool result = false;\r\n        var a = polygon.Last();\r\n        foreach (var b in polygon) {\r\n            if ((b.x == point.x) && (b.z == point.z))\r\n                return true;\r\n\r\n            if ((b.z == a.z) && (point.z == a.z)) {\r\n                if ((a.x <= point.x) && (point.x <= b.x))\r\n                    return true;\r\n\r\n                if ((b.x <= point.x) && (point.x <= a.x))\r\n                    return true;\r\n            }\r\n\r\n            if ((b.z < point.z) && (a.z >= point.z) || (a.z < point.z) && (b.z >= point.z)) {\r\n                if (b.x + (point.z - b.z) / (a.z - b.z) * (a.x - b.x) <= point.x)\r\n                    result = !result;\r\n            }\r\n            a = b;\r\n        }\r\n        return result;\r\n    }\r\n    v3 BoardPosToWorldPos(v2 boardPos) {\r\n        return new v3(-2f+boardPos.x, 0f, -2f+boardPos.y);\r\n    }\r\n    v2 WorldPosToBoardPos(v3 worldPos) {\r\n        return new v2(Mathf.FloorToInt(2f+worldPos.x), Mathf.FloorToInt(2f+worldPos.z));\r\n    }\r\n    v3 TriPosToWorldPos(float tx, float ty) {\r\n        return new v3(-2f + 0f + tx * (4f/12f), 0f, -2f + 0f + ty * (4f/12f));\r\n    }\r\n    bool IsPointOnBoard(v2 boardPoint) {\r\n        int x = Mathf.FloorToInt(boardPoint.x);\r\n        int y = Mathf.FloorToInt(boardPoint.y);\r\n        return 0 <= x && x <= 4\r\n            && 0 <= y && y <= 4;\r\n    }\r\n    bool PtsEqual((int,int) p1, (int,int) p2) {\r\n        return p1.Item1 == p2.Item1 && p1.Item2 == p2.Item2;\r\n    }\r\n    bool TrisEqual(List<(int,int)> t1, List<(int,int)> t2) {\r\n        for (int i = 0; i < 3; i++) {\r\n            if (!PtsEqual(t1[i], t2[i]))\r\n                return false;\r\n        }\r\n        return true;\r\n    }\r\n    List<List<(int,int)>> GetTris(List<v3> points) {\r\n        return allTris.Where(tri => {\r\n            float cx = (tri[0].Item1 + tri[1].Item1 + tri[2].Item1) / 3f;\r\n            float cy = (tri[0].Item2 + tri[1].Item2 + tri[2].Item2) / 3f;\r\n            v3 pos = TriPosToWorldPos(cx, cy);\r\n            return IsPointInPolygon(points, pos);\r\n        }).ToList();\r\n    }\r\n    bool IsPieceOverlapping(List<List<(int,int)>> occupiedTris, List<List<(int,int)>> pieceTris) {\r\n        for (int i = 0; i < occupiedTris.Count; i++) {\r\n            for (int j = 0; j < pieceTris.Count; j++) {\r\n                if (TrisEqual(occupiedTris[i], pieceTris[j]))\r\n                    return true;\r\n            }\r\n        }\r\n        return false;\r\n    }\r\n    List<List<(int,int)>> GetOccupiedTris() {\r\n        return placedPieces.SelectMany(piece => {\r\n            v3 pos = piece.gameObject.Pos();\r\n            v2 boardPoint = WorldPosToBoardPos(pos);\r\n            var translatedPts = GetTranslatedPoints(piece, boardPoint);\r\n            var verts = piece.windingOrder.Select(ind => BoardPosToWorldPos(translatedPts[ind])).ToList();\r\n            return GetTris(verts);\r\n        }).ToList();\r\n    }\r\n    List<v2> GetTranslatedPoints(Piece p, v2 boardPoint) {\r\n        return p.points.Select(point => boardPoint + point).ToList();\r\n    }\r\n    List<v2> GetValidPoints(Gob pieceGob) {\r\n        List<v2> allPoints = boardPiece.points;\r\n        Piece piece = pieceGob.gc<Piece>();\r\n\r\n        var occupiedTris = GetOccupiedTris();\r\n\r\n        List<v2> validPoints = allPoints.Where(boardPoint => {\r\n            List<v2> piecePoints = GetTranslatedPoints(piece, boardPoint);\r\n\r\n            // must be on the board\r\n            if (!piecePoints.All(pt => IsPointOnBoard(pt)))\r\n                return false;\r\n\r\n            // and not overlapping with a placed piece\r\n            var verts = piece.windingOrder.Select(ind => BoardPosToWorldPos(piecePoints[ind])).ToList();\r\n            var pieceTris = GetTris(verts);\r\n\r\n            bool overlapping = IsPieceOverlapping(occupiedTris, pieceTris);\r\n            return !overlapping;\r\n        }).ToList();\r\n        return validPoints;\r\n    }\r\n    v3 GetClosestWorldPoint(Gob piece, List<v2> boardPoints) {\r\n        v3 piecePos = piece.Pos();\r\n        List<v3> worldPoints = boardPoints.Select(point => BoardPosToWorldPos(point))\r\n                                          .OrderBy(point => v3.Distance(piecePos, point))\r\n                                          .ToList();\r\n        return worldPoints[0];\r\n    }\r\n    v2 RotatePoint90CW(v2 pt) {\r\n        return new v2(pt.y, -pt.x);\r\n    }\r\n    float Rotate90CW(float rotation) {\r\n        rotation += 90f;\r\n        if (rotation >= 360f)\r\n            rotation = 0f;\r\n        return rotation;\r\n    }\r\n    bool ValidPlacement(Gob piece, out v3 closestWorldPoint) {\r\n        List<v2> validPoints = GetValidPoints(piece);\r\n        if (validPoints.Count > 0) {\r\n            closestWorldPoint = GetClosestWorldPoint(piece, validPoints);\r\n            if (v3.Distance(closestWorldPoint, piece.Pos()) < dropDist)\r\n                return true;\r\n        }\r\n        \r\n        closestWorldPoint = v3.zero;         \r\n        return false;\r\n    }\r\n\r\n    ///////////\r\n    // BEHAVIOR\r\n    ///////////\r\n    void RotatePieceCW(Gob pieceGob, v3 pos, int rotateCount, bool animate=true) {\r\n        Piece piece = pieceGob.gc<Piece>();\r\n        v2 oldPivot = piece.pivot;\r\n        \r\n        for (int r = 0; r < rotateCount; r++) {\r\n            piece.rotation = Rotate90CW(piece.rotation);\r\n            v2 newPivot = RotatePoint90CW(piece.pivot);\r\n            piece.points = piece.points.Select(pt => RotatePoint90CW(pt)).ToList();\r\n            piece.pivot = newPivot;\r\n        }\r\n        \r\n        // translate\r\n        v3 oldPivot3 = new v3(oldPivot.x, 0f, oldPivot.y);\r\n        v3 pivot3 = new v3(piece.pivot.x, 0f, piece.pivot.y);\r\n        v3 startPos = pieceGob.transform.position;\r\n        v3 endPos = startPos + (oldPivot3 - pivot3);\r\n        IEnumerator _() {\r\n            float t = 0f;\r\n            float dur = 0.3f;\r\n            while (t < dur) {\r\n                float perc = t/dur;\r\n                perc = Mathf.Sin (perc * Mathf.PI * 0.5f);\r\n\r\n                v3 pos = v3.Lerp(startPos, endPos, perc);\r\n                pieceGob.transform.position = new v3(pos.x, pieceGob.transform.position.y, pos.z);\r\n\r\n                t += Time.deltaTime;\r\n                yield return new WaitForEndOfFrame();\r\n            }\r\n            pieceGob.transform.position = endPos;\r\n        }\r\n        \r\n        if (animate)\r\n            StartCoroutine(_());\r\n        else {\r\n            pieceGob.transform.rotation = Quaternion.Euler(0f, piece.rotation, 0f);\r\n            endPos.y = pieceGob.transform.position.y;\r\n            pieceGob.transform.position = endPos;\r\n        }\r\n    }\r\n    Bounds ReturnPiece(Piece p, bool draw=true, List<Bounds> finalBounds=null) {\r\n        p.toPos = p.initPos;\r\n        p.lerpPos = true;\r\n\r\n        // move out radially from center\r\n        Gob pieceGob = p.gameObject;\r\n        v3 pos = pieceGob.transform.GetChild(0).position;\r\n        // v3 pos = pieceGob.Pos();\r\n        v3 dir = pos.normalized;\r\n        if (dir.magnitude < 1f)\r\n            dir = v3.right;\r\n\r\n        Bounds final = DeintersectPiece(pieceGob, dir, draw, finalBounds);\r\n        placedPieces.Remove(p);\r\n        return final;\r\n    }\r\n    Bounds DeintersectPiece(Gob pieceGob, v3 dir, bool draw, List<Bounds> finalBounds) {\r\n        // collect bounds\r\n        Bounds pieceB = pieceGob.transform.GetChild(0).gameObject.gc<MeshRenderer>().bounds;\r\n        List<Bounds> piecesBounds = pieces.Select(pieceGob => pieceGob.transform.GetChild(0).gameObject.gc<MeshRenderer>().bounds).ToList();\r\n        if (finalBounds != null)\r\n            piecesBounds.AddRange(finalBounds);\r\n        piecesBounds.ForEach(bounds => bounds.Expand(0.25f));\r\n        \r\n        v3 pivotToCenter = pieceB.center-pieceGob.Pos();\r\n        pivotToCenter.y = 0f;\r\n        v3 center0 = pieceB.center;\r\n        pieceB.center = v3.zero;\r\n        // bool intersect = boardB.Intersects(pieceB);\r\n        v3 delta = dir * 0.1f;\r\n        for (int i = 0; i < 1000; i++) {\r\n            bool intersect = pieceB.Intersects(boardB) || piecesBounds.Any(pb => pieceB.Intersects(pb));\r\n            pieceB = new Bounds(pieceB.center+delta, pieceB.size);\r\n            if (!intersect)\r\n                break;\r\n        }\r\n        v3 centerDelta = pieceB.center-center0;\r\n        pieceGob.gc<Piece>().toPos = center0 + centerDelta - pivotToCenter; //; //- pieceB.extents;\r\n        return pieceB;\r\n    }\r\n\r\n    ///////\r\n    // MAIN\r\n    ///////\r\n    void GameOver() {\r\n        canvasGob.On();\r\n        gameOver = true;\r\n    }\r\n    public void OnRestart() {\r\n        SceneManager.LoadScene(SceneManager.GetActiveScene().name);\r\n    }\r\n    public void HardReset() {\r\n        PlayerPrefs.DeleteAll();\r\n        OnRestart();\r\n    }\r\n\r\n    ///////////////\r\n    // UNITY EVENTS\r\n    ///////////////\r\n    void Awake() {\r\n        // get all board points\r\n        Piece p = gameObject.gc<Piece>();\r\n        p.points = new List<v2>();\r\n        for (int i = 0; i < 5; i++) {\r\n            for (int j = 0; j < 5; j++) {\r\n                p.points.Add(new v2(i,j));\r\n            }\r\n        }\r\n\r\n        // get all tris\r\n        allTris = new();\r\n        List<v2> octCenters = new List<v2>();\r\n        for (int i = 0; i < 6; i++) {\r\n            for (int j = 0; j < 6; j++) {\r\n                octCenters.Add(new v2(1+i*2, 1+j*2));\r\n            }\r\n        }\r\n        octCenters.ForEach(center => {\r\n            int cx = Mathf.FloorToInt(center.x);\r\n            int cy = Mathf.FloorToInt(center.y);\r\n\r\n            // top 4\r\n            allTris.Add(new() {(cx,cy), (cx-1,cy), (cx-1,cy+1)});\r\n            allTris.Add(new() {(cx,cy), (cx-1,cy+1), (cx,cy+1)});\r\n            allTris.Add(new() {(cx,cy), (cx,cy+1), (cx+1,cy+1)});\r\n            allTris.Add(new() {(cx,cy), (cx+1,cy+1), (cx+1,cy)});\r\n\r\n            // bot 4\r\n            allTris.Add(new() {(cx,cy), (cx-1,cy-1), (cx-1,cy)});\r\n            allTris.Add(new() {(cx,cy), (cx,cy-1), (cx-1,cy-1)});\r\n            allTris.Add(new() {(cx,cy), (cx+1,cy-1), (cx,cy-1)});\r\n            allTris.Add(new() {(cx,cy), (cx+1,cy), (cx+1,cy-1)});\r\n        });\r\n\r\n        // get board bounds\r\n        boardB = boardBounds.gc<MeshRenderer>().bounds;\r\n        boardB.Expand(1f);\r\n\r\n        // place pieces\r\n        float subangle = Mathf.PI*2f/pieces.Count;\r\n        List<int> inds = new();\r\n        for (int i = 0; i < pieces.Count; i++) inds.Add(i);\r\n        inds.Shuffle();\r\n        pieceColors.Shuffle();\r\n        for (int i = 0; i < pieces.Count; i++) {\r\n            Gob pieceGob = pieces[i];\r\n            Piece piece = pieceGob.gc<Piece>();\r\n\r\n            // place\r\n            float theta = subangle*inds[i];\r\n            v3 center = new v3(-1f, 0f, -1f);\r\n            v3 pos = center + new v3(Mathf.Cos(theta), 0f, Mathf.Sin(theta)) * maxDist;\r\n\r\n            // rand init rotation\r\n            int rotateCount = Mathf.FloorToInt(1f+randf()*4f);\r\n            RotatePieceCW(pieceGob, pieceGob.Pos(), rotateCount, false);\r\n            \r\n            // state init\r\n            piece.initPos = pos;\r\n            pieceGob.Pos(center);\r\n\r\n            v3 pivot = new v3(piece.pivot.x, 0f, piece.pivot.y);\r\n            piece.childOffset = pieceGob.transform.GetChild(0).localPosition - pivot;\r\n            pieceGob.transform.GetChild(0).gameObject.gc<MeshRenderer>().material.color = pieceColors[i].alpha(0.5f);\r\n        }\r\n\r\n        // move pieces outside board\r\n        List<Bounds> finals = new List<Bounds>();\r\n        pieces.ForEach(pieceGob => {\r\n            Piece piece = pieceGob.gc<Piece>();\r\n            Bounds final = ReturnPiece(piece, true, finals);\r\n            finals.Add(final);\r\n        });\r\n    }\r\n    void Update() {\r\n        // reset colors\r\n        pieces.ForEach(pieceGob => {\r\n            Color c = pieceGob.transform.GetChild(0).gameObject.gc<MeshRenderer>().material.color.alpha(1f);\r\n            pieceGob.transform.GetChild(0).gameObject.gc<MeshRenderer>().material.color = c;\r\n        });\r\n        \r\n        // return;\r\n        if (gameOver)\r\n            return;\r\n        \r\n        trash.ForEach(e => kill(e));\r\n        trash.Clear();\r\n\r\n        // piece debug\r\n        pieces.ForEach(pieceGob => {\r\n            // movement dir\r\n            Piece piece = pieceGob.gc<Piece>();\r\n            Debug.DrawLine(pieceGob.Pos(), piece.toPos, Color.red);\r\n            \r\n            // bounds\r\n            Bounds pieceB = pieceGob.transform.GetChild(0).gameObject.gc<MeshRenderer>().bounds;\r\n            DrawBounds(pieceB);\r\n\r\n            // pivot to center\r\n            v3 pivotToCenter = pieceB.center-pieceGob.Pos();\r\n            Debug.DrawLine(pieceGob.Pos(), pieceGob.Pos()+pivotToCenter, Color.magenta);\r\n        });\r\n\r\n        // board bounds debug\r\n        DrawBounds(boardB);\r\n\r\n        // lerp piece rotations\r\n        pieces.ForEach(pieceGob => {\r\n            Piece piece = pieceGob.gc<Piece>();\r\n            v3 angles = pieceGob.transform.localEulerAngles;\r\n            float smooth = 15f;\r\n            pieceGob.transform.rotation = Quaternion.Lerp(pieceGob.transform.rotation, Quaternion.Euler(0f, piece.rotation, 0f), lerpdt(smooth, Time.deltaTime));\r\n        });\r\n\r\n        // lerp piece positions\r\n        pieces.ForEach(pieceGob => {\r\n            Piece piece = pieceGob.gc<Piece>();\r\n            if (piece.lerpPos) {\r\n                float smooth = 15f;\r\n                pieceGob.transform.position = v3.Lerp(pieceGob.transform.position, piece.toPos, lerpdt(smooth, Time.deltaTime));\r\n            }\r\n        });\r\n\r\n        // mouse raycast\r\n        Ray r = cam.ScreenPointToRay(Input.mousePosition);\r\n        RaycastHit hit;\r\n        Physics.Raycast(r, out hit, 1000f, 1 << 3);\r\n\r\n        // hover\r\n        if (selectedPiece != null) {\r\n            Color c = selectedPiece.transform.GetChild(0).gameObject.gc<MeshRenderer>().material.color.alpha(0.5f);\r\n            selectedPiece.transform.GetChild(0).gameObject.gc<MeshRenderer>().material.color = c;\r\n        }\r\n        else if (hit.collider != null) {\r\n            Gob pieceGob = hit.collider.gameObject.Parent();\r\n            Color c = pieceGob.transform.GetChild(0).gameObject.gc<MeshRenderer>().material.color.alpha(1f);\r\n            pieceGob.transform.GetChild(0).gameObject.gc<MeshRenderer>().material.color = c;\r\n        }\r\n\r\n        // select piece\r\n        if (Input.GetMouseButtonDown(0) && selectedPiece == null) {\r\n            if (hit.collider != null) {\r\n                selectedPiece = hit.collider.gameObject.Parent();\r\n                selectionOffset = hit.point - selectedPiece.Pos();\r\n                selectionOffset.y = 0f;\r\n                mouseDownPos = Input.mousePosition;\r\n                dragDist = 0f;\r\n                Piece piece = selectedPiece.gc<Piece>();\r\n                piece.lerpPos = false;\r\n                placedPieces.Remove(piece);\r\n\r\n                // ghost\r\n                selectedPieceGhost = make(selectedPiece);\r\n                selectedPieceGhost.transform.GetChild(0).gameObject.gc<MeshRenderer>().material = ghostMat;\r\n                Color c = selectedPiece.transform.GetChild(0).gameObject.gc<MeshRenderer>().material.color.alpha(0.25f);\r\n                selectedPieceGhost.transform.GetChild(0).gameObject.gc<MeshRenderer>().material.color = c;\r\n                selectedPieceGhost.Off();\r\n            }\r\n        }\r\n        \r\n        // drag piece\r\n        if (Input.GetMouseButton(0) && selectedPiece != null) {\r\n            RaycastHit hit1;\r\n            Physics.Raycast(r, out hit1, 1000f, 1 << 6);\r\n            if (hit1.collider != null) {\r\n                v3 delta = Input.mousePosition - mouseDownPos;\r\n                dragDist += delta.magnitude;\r\n                mouseDownPos = Input.mousePosition;\r\n\r\n                // vertical offset\r\n                float percMoved = dragDist/Screen.width;\r\n                if (percMoved > 0.025f) {\r\n                    v3 pos = hit1.point;\r\n                    pos.y = 0.5f;\r\n                    selectedPiece.Pos(pos - selectionOffset);\r\n                }\r\n\r\n                // ghost\r\n                v3 closestWorldPoint = v3.zero;\r\n                if (ValidPlacement(selectedPiece, out closestWorldPoint)) {\r\n                    selectedPieceGhost.On();\r\n                    selectedPieceGhost.Pos(closestWorldPoint);\r\n                }\r\n                else {\r\n                    selectedPieceGhost.Off();\r\n                }\r\n            }\r\n        }\r\n\r\n        // mouse up\r\n        if (Input.GetMouseButtonUp(0) && selectedPiece != null) {\r\n            Piece piece = selectedPiece.gc<Piece>();\r\n            float percMoved = dragDist/Screen.width;\r\n\r\n            // rotate piece\r\n            if (percMoved < 0.05f) {\r\n                // return if placed\r\n                v3 closestPoint = v3.zero;\r\n                if (ValidPlacement(selectedPiece, out closestPoint))\r\n                    ReturnPiece(piece);\r\n\r\n                // rotate                \r\n                else\r\n                   RotatePieceCW(selectedPiece, selectedPiece.gc<Piece>().initPos, 1);\r\n\r\n                // deselect\r\n                selectedPiece = null;\r\n\r\n                // ghost\r\n                kill(selectedPieceGhost);\r\n                selectedPieceGhost = null;\r\n            }\r\n\r\n            // drop piece\r\n            else {\r\n                List<v2> validPoints = GetValidPoints(selectedPiece);\r\n                bool validDrop = false;\r\n                if (validPoints.Count > 0) {\r\n                    v3 closestWorldPoint = GetClosestWorldPoint(selectedPiece, validPoints);\r\n                    if (v3.Distance(closestWorldPoint, selectedPiece.Pos()) < dropDist)\r\n                        validDrop = true;\r\n                }\r\n\r\n                // drop if there's room\r\n                if (validDrop) {\r\n                    v3 closestWorldPoint = GetClosestWorldPoint(selectedPiece, validPoints);\r\n                    selectedPiece.Pos(closestWorldPoint);\r\n                    placedPieces.Add(selectedPiece.gc<Piece>());\r\n\r\n                    // move back down\r\n                    v3 childPos = selectedPiece.transform.GetChild(0).localPosition;\r\n                    childPos.y = 0f;\r\n                    selectedPiece.transform.GetChild(0).localPosition = childPos;\r\n                }\r\n\r\n                // return to pickup pos\r\n                else\r\n                    ReturnPiece(piece);\r\n\r\n                // deselect\r\n                selectedPiece = null;\r\n\r\n                // ghost\r\n                kill(selectedPieceGhost);\r\n                selectedPieceGhost = null;\r\n\r\n                // check for win\r\n                if (placedPieces.Count == 7)\r\n                    GameOver();\r\n            }\r\n        }\r\n    }\r\n    void LateUpdate() {\r\n        // get bounds around board and all pieces\r\n        Bounds superBounds = gameOver ? boardBounds.gc<MeshRenderer>().bounds\r\n                                      : boardB;\r\n        if (!gameOver) {\r\n            pieces.ForEach(pieceGob => {\r\n                Bounds pb = pieceGob.transform.GetChild(0).gameObject.gc<MeshRenderer>().bounds;\r\n                superBounds.Encapsulate(pb);\r\n            });\r\n            superBounds.Expand(1f);\r\n        }\r\n        else\r\n            superBounds.Expand(-1f);\r\n        DrawBounds(superBounds);\r\n\r\n        float smooth = 15f;\r\n        \r\n        // lerp cam pos\r\n        v3 center = superBounds.center;\r\n        v3 camPos = cam.gameObject.Pos();\r\n        camPos.x = center.x;\r\n        camPos.z = center.z;\r\n        cam.gameObject.Pos(v3.Lerp(cam.gameObject.Pos(), camPos, lerpdt(smooth, Time.deltaTime)));\r\n\r\n        // lerp cam size\r\n        v3 extents = superBounds.extents;\r\n        float camHeight = extents.x > extents.z ? extents.x * (Screen.height/Screen.width)\r\n                                               : extents.z;\r\n        cam.orthographicSize = Mathf.Lerp(cam.orthographicSize, camHeight, lerpdt(smooth, Time.deltaTime));\r\n    }\r\n}";